        Read the timeline's subtitle track(s) as transcript text. This is the
        TIMELINE subtitle transcript that propose_cuts consumes; it is separate
        from clip-level transcription (produced by transcribe_audio on a
        folder/clip, read via media_pool_item get_transcription), which does not
        drive timeline cuts.
      propose_cuts(cues?, long_pause_frames?) -> {cuts, cut_count, basis_cue_count, pass, note}
        DRY-RUN. Mechanically detect candidate cuts (filler words, long pauses,
        repeated lines) from the subtitle transcript. Proposes only; applies nothing.
      apply_cuts(cuts, dry_run?, confirm_token?, allow_partial_item_delete?) -> {applied, total, skipped, results}
        skipped lists cuts that were not applicable, each with a reason.
        Apply a CutList (from propose_cuts) as lift/ripple deletes. DRY-RUN by
        default; applying is DESTRUCTIVE — confirm-token gated and a timeline
        version is archived first. Cuts apply latest-first.
      get_mark_in_out() -> {mark}
      set_mark_in_out(mark_in, mark_out, type?) -> {success}
      clear_mark_in_out(type?) -> {success}
      convert_to_stereo() -> {success}
      get_items_in_track(track_type, track_index|index) -> {items}  — alias of get_items
      get_voice_isolation_state(track_index) -> {isEnabled, amount}
      set_voice_isolation_state(track_index, state) -> {success}
      extract_source_frame_ranges(handles?, gap_max?, skip_extensions?) -> {timeline_name, frame_ranges, occurrences, ...}
        — Same logic as Pr/extract_timeline_frames.py get_resolve_api_frames: all video clips on the
        current timeline; clip name = basename of Media Pool File Path when set; skips audio extensions.
        source_range_final and frame_ranges tuples are inclusive/inclusive endpoints per that script.
        Default handles=24, gap_max=30. Use handles=0 for gap-only auto handles.
      conform_capabilities() -> {supported, partially_supported, unsupported, export_aliases}
      probe_timeline_structure(track_types?, include_markers?, include_clip_properties?) -> {tracks, markers}
        Each item reports source_start/source_end (SOURCE frames, end EXCLUSIVE) in the
        MEDIA's frame rate, the source_fps they are counted in, and
        source_start_seconds/source_end_seconds. Use the reported source_fps — a WAV
        freezes the PROJECT's rate at import, so it differs from the timeline whenever
        the project moved afterwards, and dividing by the timeline rate is then wrong by
        minutes. source_fps is null when the rate could not be read; treat the frames as
        unitless then, do not assume the timeline's. All four source_* fields are
        FILE-relative — frame 0 is the head of the media, whatever timecode the camera
        stamped on it. source_end is the span between Resolve's source second-readers
        anchored on source_start, so it is a source frame even when the rates differ and
        even on media with a non-zero start TC (those readers are timecode-absolute; the
        offset cancels in the span). It falls back to source_start + TIMELINE duration
        (unit-mixed) only when those readers or the rate are unavailable.
      detect_gaps_overlaps(track_types?, min_gap?) -> {gaps, overlaps}
      source_range_report(handles?, merge?) -> {ranges, occurrences}
      export_timeline_checked(path, format?|type?, subtype?, require_temp_path?, dry_run?, background?) -> {success, path, size | job_id}
      import_timeline_checked(path, options?, timeline_name?, import_source_clips?, sanitize_media?, require_temp_path?, dry_run?, background?) -> {success, name, id, media, sanitize?, warning? | job_id}
        Imports an FCP7 xmeml / FCPXML / AAF timeline. AAF (.aaf) is read natively by
        Resolve — the XML sanitize pass is SKIPPED for it (media relinks via the media
        pool, not by rewriting the file); a `note` says so. For AAF, passing
        relink_search_roots triggers a POST-import media-pool relink (RelinkClips against
        each root) — fuzzy-relink parity by a media-pool mechanism; the `relink` block
        reports before/after coverage. Premiere .prproj has no Resolve importer — refused
        with a message pointing to the advanced MCP's offline read + convert_to_interchange
        bridge (no Premiere needed). `media` reports {total, linked, offline}
        coverage; `warning` flags offline items. sanitize_media=True (recommended for
        Premiere/FCP exports) rewrites the XML first — dropping clipitems that reference
        MISSING media or are generators (slug/solid with no media file), both of which
        otherwise abort the scripting-API import and leave the whole timeline offline.
        Returns `sanitize` with the kept/removed breakdown. The original is only read;
        the sanitized copy goes to a temp dir (no require_temp_path needed when sanitizing).
        relink_search_roots (str|list) enables fuzzy relink: clips missing at their
        original path are matched against media under those roots (exact/ext-agnostic/
        normalized/reel + IDF true-source) and their pathurl rewritten so they relink
        instead of being dropped. relink_min_confidence (default 0.7) gates matches;
        `sanitize.relinked` / `sanitize.ambiguous` report the outcome.
        verify_visually=True (or passing reference_movie) frame-checks each proposed
        relink against a reference (reference_movie at the clip's record position, else
        the offline proxy at the original path) using a brightness-robust SSIM-structure
        metric; a conflicting relink is VETOED — reverted and reported under
        `sanitize.flagged` for human review, never silently applied. verify_threshold
        (default 0.90) sets the structural-match bar.
      import_from_drp(drpPath, timelineNames?|timelineIndexes?, import_source_clips?, dry_run?) -> {success, selected, imported, available, results, partial?}
        timelineNames are the POOL's names (a SeqContainer's own first <Name>
        is a clip's — measured E129); `available` rows carry kind
        (timeline|compound). Omitted selection = every TIMELINE: a compound's
        inner container is not a timeline of its own, it travels with the
        timeline that places it (kept recursively in the extracted .drt, E130).
        CAVEAT (measured 19.1.3.7): Resolve refuses extracted containers even
        repacked with the source's project.xml — the sufficient import set
        beyond Resolve's own .drt exports is unmapped, so expect failures on
        this build and read results[].error; success reflects the rows. For a
        reliable programmatic import use OTIO or FCP7 XML.
        Extract chosen timelines from a .drp (offline zip surgery → temp .drt each) and
        import each into the running Resolve. Omit the selector to import ALL. Enumerate
        first with the advanced MCP drt.list_sequences / editorial.list_sequences to get
        [{id, name, eventCount}] for a "which sequence?" picker. Requires Resolve open.
      compare_timelines(right_timeline_id?|right_timeline_index?|left_snapshot?, right_snapshot?) -> {match, differences}
      probe_interchange_roundtrip(format?, output_dir?, cleanup_imported?) -> {success, export, import, comparison}
      detect_missing_media(sanitized?|sanitize_paths?, omit_raw_paths?) -> {missing, missing_count, diagnosis}
      build_relink_plan(search_roots, max_depth?, max_seconds?, max_files_scanned?, skip_search_when_volume_missing?, sanitized?) -> {candidates, diagnosis}
      conform_boundary_report(...) -> {capabilities, timeline, gaps_overlaps, source_ranges, missing_media}
      audio_capabilities() -> {supported, partially_supported, unsupported}
      probe_audio_item(track_type?, track_index?, item_index?) -> {summary, audio_properties, source_audio_mapping}
      probe_audio_track(track_index?) -> {track_count, enabled, locked, sub_type, voice_isolation}
      safe_set_audio_properties(properties, restore?, dry_run?, track_type?, track_index?, item_index?) -> {success, results}
      audio_mix_capability_report(...) -> {capabilities, mix_recommendations}
      voice_isolation_capabilities(track_index?, track_type?, item_index?) -> {timeline_track, item}
      audio_mapping_report(clip_ids?) -> {timeline_items, media_pool_items}
      safe_auto_sync_audio(clip_ids|selected, settings?, dry_run?) -> {success}
      transcription_capabilities(clip_ids?|selected?) -> {clip_methods, folder}
      subtitle_generation_probe(settings?, allow_generate?) -> {success}
      fairlight_boundary_report(...) -> {capabilities, track, item, audio_mapping, transcription}

