  name?: string;
  // Maximum seconds to wait for the code to finish executing. 1-30, default 20.
  response_timeout_secs?: number;
  // JavaScript/TypeScript source. Must export a default async function: `export default async (ctx) => { ... }`. ctx.args holds the input parameters (declare them via `parameters` in `body`); ctx.config holds plain string variables mapped into the tool's execution_context. ctx.secrets and ctx.auth_connections are write-only credential references: a secret can only be interpolated into a fetch request header (e.g. `Authorization: Bearer ${ctx.secrets.MY_KEY}`) and an auth connection only into the `X-With-Auth-Connection` header; neither can be read or logged. There is no ctx.env, and npm dependencies are not supported: only the sandbox runtime's built-ins (e.g. fetch) are available.
  source_code?: string;
}): Promise<CallToolResult>; };
