exec tool declaration:
```ts
declare const tools: { mcp__elevenlabs__creative_design_voice(args: {
  // Why are you calling this tool? Briefly describe the user's goal.
  context: string;
  // How closely the previews follow voice_description versus sounding natural. Higher follows the description more strictly.
  guidance_scale?: number;
  // ISO language code for text. From the user, never guessed from voice_description alone.
  language: string;
  // Target loudness, from -1 (quietest) to 1 (loudest).
  loudness?: number;
  // The voice design model. Use eleven_ttv_v3 unless the user asks for the older multilingual model.
  model_id?: "eleven_ttv_v3" | "eleven_multilingual_ttv_v2";
  // Higher quality gives a better voice but less variety. Only accepted with eleven_multilingual_ttv_v2; passing it with eleven_ttv_v3 is rejected.
  quality?: number;
  // Fixes the randomness so a repeat call reproduces the same previews. Omit for a fresh set each time.
  seed?: number;
  // Whether to enhance the generated previews. Leave at the default unless the user asks otherwise.
  should_enhance?: boolean;
  // The line the previews will speak. Obtained from the user, never invented or auto-generated — this is what they will judge the voice by.
  text: string;
  // Set by the voice-design view when the user edits the line and hits Regenerate — never set this yourself. It replaces that view's previews with the new round instead of minting a separate view. Regenerating still spends credits like any other call to this tool: if you genuinely want another round, call this tool again with no view_state_id rather than passing this.
  view_state_id?: string;
  // What the voice should sound like — age, accent, tone, pacing, emotion. From the user's own words, never invented.
  voice_description: string;
}): Promise<CallToolResult<{
  error?: string;
  language?: string;
  model_id?: string;
  notes?: string;
  // Candidate voices generated from voice_description, for the user to pick between.
  previews?: Array<{
  // Short-lived signed URL for the preview sample. Absent when no sample has landed for this preview yet.
  audio_url?: string;
  duration_secs?: number;
  generated_voice_id: string;
  language?: string;
  orb_url?: string;
  [key: string]: unknown;
}>;
  // The previews[].generated_voice_id that was saved — lets the view mark which preview row is the saved one. Distinct from saved_voice_id, which is the library voice id.
  saved_generated_voice_id?: string;
  // Present once creative_save_designed_voice has saved a preview into the workspace's voice library. Usable with creative_generate_speech.
  saved_voice_id?: string;
  saved_voice_name?: string;
  // An openable link to the saved voice in the web app. Set only once the voice exists, so there is nothing to share before then.
  saved_voice_url?: string;
  text?: string;
  // For the view only — present when this call originates the voice-design view.
  view_kind?: "voice_design";
  // For the view only — a message about the view's own build.
  view_notice?: { level: "subtle" | "blocking"; message: string; [key: string]: unknown; };
  // For the view only — pass it to creative_get_view_state and creative_save_view_state so it can rehydrate after a reload. Present only when this call originates a new view; absent on a status poll, since the view already holds the id from the payload it first mounted with.
  view_state_id?: string;
  voice_description?: string;
  [key: string]: unknown;
}>>; };
