declare const tools: { mcp__elevenlabs__creative_edit_image(args: {
  // Existing node IDs that should feed INTO this new node. Pass these when you already know the upstream wiring — the canvas places the new node correctly on creation instead of parking it first and reflowing later. This is how a reference node created by creative_upload_flow_reference (or creative_add_flow_asset_node) gets wired into this generation — the node must already exist on this same flow_id. A node_id only ever comes from a tool result, creative_upload_flow_reference's widget context, or creative_get_flow — never from memory or invention. If you do not have one yet, call creative_get_flow and read it from there rather than guessing a name like 'reference'. For an image edit driven by a reference — 'change X into Y in this image' — use gpt-image-2 unless the user names a model. It is the default for this specifically; the plain text-to-image default does not apply once a reference is wired.
  connect_from?: Array<string>;
  // Why are you calling this tool? Briefly describe the user's goal.
  context: string;
  // Return the credit cost and any blocking node errors without generating anything. Worth doing before a long video or several variations, so the user can approve the spend first.
  estimate_only?: boolean;
  // The flow to act on, as returned by creative_create_flow or creative_generate_in_flow. Omit it for a one-off generation and a new flow is created. Always pass it when this generation will be combined with another: nodes on different flows cannot be connected, so allocate one with creative_create_flow up front and reuse it.
  flow_id?: string;
  // How many variations to produce, so the user can pick. Defaults to 4 so the user can pick from several options — keep it at 4 unless the user asks for a specific number. Costs scale with the count.
  generations_count?: number;
  // The model to generate with. Use gpt-image-2 unless the user asks for something specific. Go looking for a different one when the request implies something the default may not do — a specific resolution or aspect, rendered text, a long duration, a named style or a named provider. creative_get_flow_node_types lists what this workspace can actually run; creative_get_model_guide explains how to prompt one. Pick by what the request needs: gpt-image-2 for rendered text, infographics, UI mockups or multi-panel layouts, and it takes up to 10 reference images; gemini-3-pro-image for editing an existing image, composing several into one, or holding a character consistent across shots; flux-2-pro for fine detail and strict prompt adherence, and the FLUX variant to pick when two or more reference images must be combined (up to 5); flux-1-kontext for a single reference image only — do not pick it to combine two or more.
  model_id: "birefnet-v2-bg-removal" | "flux-1-kontext" | "flux-2-pro" | "gemini-2.5-flash-image" | "gemini-3-pro-image" | "gemini-3.1-flash-image" | "gemini-3.1-flash-lite-image" | "gpt-image-1" | "gpt-image-1.5" | "gpt-image-2" | "gpt-image-2.5-flare" | "gpt-image-2.5-sunburst" | "krea-2-large" | "krea-2-medium" | "recraft-v4" | "recraft-v4.1" | "runway-gen4-image" | "runway-gen4-image-turbo" | "topaz-image-upscale";
  // What to generate.
  prompt: string;
}): Promise<CallToolResult<{
  all_completed?: boolean;
  error?: string;
  error_message?: string;
  // Present only for estimate_only calls. Nothing was generated and nothing was charged.
  estimate?: { blocking_errors?: Array<string>; credits?: number; currency?: string; estimated_runtime_seconds?: number; generations_count?: number; price_cents?: number; [key: string]: unknown; };
  flow_created?: boolean;
  // Pass this back to keep working on the same flow.
  flow_id?: string;
  // Canvas page for the user, without view state.
  flow_url?: string;
  // Generation records for this run, as creative_get_flow_run_status and creative_show_flow_results report them. media/pending are the view-friendly projection of the same data.
  generations?: Array<{ content_url?: string; created_at_unix_ms?: number; duration_secs?: number; error_message?: string; height?: number; id: string; modality?: string; model_id: string; price?: { cost_fiat_currency: string; credits: number; price_cents: number; [key: string]: unknown; }; prompt?: string; status: string; thumbnail_url?: string; width?: number; [key: string]: unknown; }>;
  has_failures?: boolean;
  // Finished generations. The view renders these; the URLs are short-lived and are not worth repeating back to the user.
  media?: Array<{
  // Width over height, so the view can size the tile before the bytes decode.
  aspect_ratio?: number;
  duration_secs?: number;
  generation_id: string;
  // Deep link to the generation itself, not the flow that produced it.
  generation_url?: string;
  kind: "image" | "video" | "audio";
