  flow_id: string;
  // How many variations to produce, so the user can pick. Video nodes always produce one. Defaults to 4 so the user can pick from several options — keep it at 4 unless the user asks for a specific number. Costs scale with the count.
  generations_count?: number;
  // The nodes to generate on.
  node_ids: Array<string>;
}): Promise<CallToolResult<{
  all_completed?: boolean;
  error?: string;
  error_message?: string;
  // Present only for estimate_only calls. Nothing was generated and nothing was charged.
  estimate?: { blocking_errors?: Array<string>; credits?: number; currency?: string; estimated_runtime_seconds?: number; generations_count?: number; price_cents?: number; [key: string]: unknown; };
  flow_created?: boolean;
  // Pass this back to keep working on the same flow.
  flow_id?: string;
  // Canvas page for the user, without view state.
  flow_url?: string;
  // Generation records for this run, as creative_get_flow_run_status and creative_show_flow_results report them. media/pending are the view-friendly projection of the same data.
  generations?: Array<{ content_url?: string; created_at_unix_ms?: number; duration_secs?: number; error_message?: string; height?: number; id: string; modality?: string; model_id: string; price?: { cost_fiat_currency: string; credits: number; price_cents: number; [key: string]: unknown; }; prompt?: string; status: string; thumbnail_url?: string; width?: number; [key: string]: unknown; }>;
