  duration_secs?: number;
  generation_id: string;
  // Deep link to the generation itself, not the flow that produced it.
  generation_url?: string;
  kind: "image" | "video" | "audio";
  // Full-resolution asset, used for the Download action.
  master_url?: string;
  model_id?: string;
  poster_url?: string;
  prompt?: string;
  // References that fed this generation (image/video/audio), with short-lived URLs to render as thumbnails.
  references?: Array<{ kind: "image" | "video" | "audio"; url: string; [key: string]: unknown; }>;
  // Model parameters this generation ran with (resolution, aspect ratio, duration...), rendered as label/value chips.
  settings?: Array<{ label: string; value: string; [key: string]: unknown; }>;
  url: string;
  // Present only for a speech generation: the voice it ran with.
  voice?: { name?: string; orb_url?: string; voice_id: string; [key: string]: unknown; };
  [key: string]: unknown;
}>;
  node_id?: string;
